"""Analyze all targets' samples: structure, limits, orthogonality, determinism."""
import json, subprocess, random
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")

def run(exe, args, stdin):
    p = subprocess.run([str(exe)] + list(args), input=stdin, cwd=str(exe.parent),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=20)
    return p.stdout.decode('utf-8', 'backslashreplace'), p.stderr.decode('utf-8', 'backslashreplace'), p.returncode

def parse3(out):
    parts = out.split()
    if len(parts) == 3:
        try:
            return int(parts[0]), int(parts[1]), int(parts[2])
        except ValueError:
            pass
    return None

# ---- T4 determinism ----
print('== T4 determinism (same input x 15) ==')
seen = {}
for i in range(15):
    out, err, rc = run(ROOT / 'T4/app.exe', [], b'hello\n')
    seen[(out, rc)] = seen.get((out, rc), 0) + 1
for k, v in seen.items():
    print(f'  x{v}: rc={k[1]} out={k[0]!r}')

# ---- per-target sample analysis ----
for t in ['t2', 't3', 't6', 't8', 't5', 't7']:
    p = ROOT / f'_work/{t}/samples.jsonl'
    if not p.exists():
        continue
    rows = [json.loads(l) for l in p.read_text(encoding='utf-8').splitlines()]
    rcs = {}
    shapes = {}
    fails = []
    for r in rows:
        rcs[r['rc']] = rcs.get(r['rc'], 0) + 1
        pr = parse3(r['out']) if r['out'] else None
        if pr:
            shapes['3num'] = shapes.get('3num', 0) + 1
        elif r['rc'] == 0:
            shapes['other-ok'] = shapes.get('other-ok', 0) + 1
        if r['rc'] != 0 or not r['out']:
            fails.append((r['label'], len(bytes.fromhex(r['stdin_hex'])), r['rc']))
    print(f'== {t}: rc={rcs} shapes={shapes}')
    # length limit from bases
    for r in rows:
        if r['label'] == 'base':
            n = len(bytes.fromhex(r['stdin_hex']))
            if r['rc'] != 0:
                print(f'   base fail: len={n} rc={r["rc"]}')
    # orthogonality: same stdin different args -> same h2?
    h2_by_stdin = {}
    viol = 0
    for r in rows:
        pr = parse3(r['out']) if r['out'] else None
        if pr:
            key = r['stdin_hex']
            if key in h2_by_stdin and h2_by_stdin[key] != pr[1]:
                viol += 1
            h2_by_stdin[key] = pr[1]
    print(f'   h2-orthogonality violations: {viol} over {len(h2_by_stdin)} stdin values')
    h1_by_args = {}
    viol1 = 0
    for r in rows:
        pr = parse3(r['out']) if r['out'] else None
        if pr:
            key = json.dumps(r['args'])
            if key in h1_by_args and h1_by_args[key] != pr[0]:
                viol1 += 1
            h1_by_args[key] = pr[0]
    print(f'   h1-orthogonality violations: {viol1}')
    # third component patterns
    h3 = {}
    for r in rows:
        pr = parse3(r['out']) if r['out'] else None
        if pr:
            h3[json.dumps(r['args'])] = pr[2]
    if len(set(h3.values())) <= 12:
        print('   h3 by args:', h3)
